var n=`0770-matoke`;var t=`world-0770`;var i=`UG`;var s=`eastern-africa`;var o=4;var r=75;var l={en:`Matoke`,ua:`Матоке`};var p={en:`Matoke is a Uganda classic prepared with plantain, banana leaf, peanut sauce. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Use green unripe cooking plantains to approximate East African matoke bananas, which are not separately listed.`,ua:`Матоке, страва кухні країни Уганда зі складниками: плантан, банановий лист, арахісовий соус. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Зелені недостиглі плантани наближено замінюють східноафриканські банани матоке, відсутні як окремий інгредієнт.`};var d=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`plantain`,1e3,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:8,i:[[`banana-leaf`,6,`leaf`]]},{en:`Steam the leaf-wrapped unripe cooking plantains until very tender, then remove leaves carefully before mashing.`,ua:`Пропарте загорнуті в листя недостиглі кулінарні плантани до повної м’якості й обережно зніміть листя перед товченням.`,t:[`banana-leaf-steaming`],m:42,i:[[`water`,450,`ml`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 12 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 12 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:12,i:[[`unsalted-butter`,40,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`peanut-sauce`,200,`g`]]}];var h={slug:n,id:t,country:`UG`,region:s,servings:4,minutes:75,title:l,text:p,steps:d};export{i as country,h as default,t as id,r as minutes,s as region,o as servings,n as slug,d as steps,p as text,l as title};